   Action<Attachment,Vector3,Vector3,int,Vector3,float,float> box=(parent,at,size,material,axis,angle,end)=>parts.Add(new Part{Name="Box",Parent=parent,Kind=Shape.Box,Position=at,Size=size,Material=material,Axis=axis,Angle=angle,End=end,Shadows=material<8&&size.sqrMagnitude>=.09f});
