   // _build_warden appends to the still-visible base body (no heavy/soldier substitution).
   box(body,new Vector3(0,1.03f,.12f),new Vector3(1.1f,.6f,.85f),0,Vector3.zero,0,0);box(body,new Vector3(0,1.37f,.2f),new Vector3(.8f,.17f,1.2f),1,Vector3.zero,0,0);box(body,new Vector3(0,1.47f,.2f),new Vector3(.3f,.14f,1.35f),3,Vector3.zero,0,0);box(body,new Vector3(0,1.02f,-.34f),new Vector3(.6f,.43f,.055f),5,Vector3.zero,0,0);
