   plate(body,new Vector3(0,1.05f,.57f),new Vector3(.68f,.4f,.035f),8);box(body,new Vector3(0,1.05f,.595f),new Vector3(.48f,.27f,.018f),10,Vector3.zero,0,20);for(int row=0;row<6;row++)box(body,new Vector3(0,.935f+row*.044f,.613f),new Vector3(.46f,.016f,.035f),9,Vector3.right,-.3f,20);foreach(float x in new[]{-.25f,.25f})box(body,new Vector3(x,1.05f,.61f),new Vector3(.022f,.30f,.04f),11,Vector3.zero,0,20);plate(turret,new Vector3(0,.13f,.07f),new Vector3(.43f,.07f,.32f),8);
